import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("ARCHIVE CONTENTS:")
for n in z.namelist():
    print(" ", n)
print()

wb = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))

rel_map = {}
for rel in rels:
    rid = rel.get("Id")
    target = rel.get("Target")
    if target.startswith("/"):
        target = target[1:]
    else:
        target = "xl/" + target
    rel_map[rid] = target

shared_strings = []
if "xl/sharedStrings.xml" in z.namelist():
    ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in ss.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        shared_strings.append(text)

print(f"SHARED STRINGS ({len(shared_strings)}):")
for i, s in enumerate(shared_strings):
    print(f"  [{i}] {s!r}")
print()

sheets = []
for sh in wb.find("m:sheets", NS):
    name = sh.get("name")
    rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    sheets.append((name, rel_map.get(rid)))

for name, sheet_path in sheets:
    print(f"=== Sheet: {name} ({sheet_path}) ===")
    ws = ET.fromstring(z.read(sheet_path))
    for row in ws.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
        cells = []
        for c in row:
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            is_ = c.find("m:is", NS)
            val = None
            if t == "s" and v is not None:
                val = shared_strings[int(v.text)]
            elif t == "inlineStr" and is_ is not None:
                val = "".join(x.text or "" for x in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            elif v is not None:
                val = v.text
            if val is not None:
                cells.append((ref, t, val))
        if cells:
            print(cells)
    print()

